import assert from 'node:assert/strict'
import { createHash } from 'node:crypto'
import { readFileSync } from 'node:fs'
import { execFileSync } from 'node:child_process'

const hash = value => createHash('sha256').update(value).digest('hex')
const root = '/workspace/pnd-baseline-144-vehicles'
const base = '860e8ae246b5237469b36a5f2c7794ce75731e95'
const candidate = 'fd9dbc1f6cd3bc3f529c893b02b13677d12f7f8b'
const load = name => {
  const receipt = JSON.parse(readFileSync(`work/orchestration/${name}`, 'utf8'))
  assert.equal(receipt.phase, 'finished')
  assert.deepEqual(receipt.source, receipt.sourceAfter)
  assert.equal(hash(receipt.stdout), receipt.stdoutSha256)
  assert.equal(hash(receipt.stderr), receipt.stderrSha256)
  return receipt
}
const full = load('issue144-vehicles-focused-fd9dbc1.json')
const previous = load('issue144-vehicles-baseline-focused-860e8ae.json')
assert.equal(full.source.headOid, candidate)
assert.equal(previous.source.headOid, base)
assert.equal(full.status, 'passed')
assert.equal(full.exitCode, 0)
assert.equal(previous.status, 'failed')
assert.equal(previous.exitCode, 1)
assert.deepEqual(full.command, previous.command)
assert.deepEqual(Object.keys(full.source.inputs), Object.keys(previous.source.inputs))
for (const [path, value] of Object.entries(full.source.inputs)) {
  assert.equal(hash(readFileSync(path)), value, path)
  if (path !== 'app/scene-entities.ts') assert.equal(value, previous.source.inputs[path], path)
}
assert.match(full.stdout, /pass 8\n.*fail 0/)
assert.match(previous.stdout, /pass 7\n.*fail 1/)
assert.match(previous.stdout, /64 survivors: 2144 ID reads/)
assert.equal(execFileSync('git', ['diff', '--name-only', 'HEAD'], { cwd: root, encoding: 'utf8' }).trim(), 'tests/follower-transport-owner-consumers.test.mjs')
assert.equal(hash(execFileSync('git', ['show', `${base}:app/scene-entities.ts`])), previous.source.inputs['app/scene-entities.ts'])
assert.equal(hash(readFileSync(`${root}/app/scene-entities.ts`)), previous.source.inputs['app/scene-entities.ts'])
const baseConsumer = execFileSync('git', ['show', `${base}:tests/follower-transport-owner-consumers.test.mjs`], { encoding: 'utf8' })
const finalConsumer = readFileSync('tests/follower-transport-owner-consumers.test.mjs', 'utf8')
const tail = value => value.slice(value.indexOf("test('vehicle damage immunity"))
assert.equal(tail(finalConsumer), tail(baseConsumer))
const lint = load('issue144-vehicles-oxlint-fd9dbc1.json')
const oldLint = load('issue144-vehicles-baseline-oxlint-860e8ae.json')
for (const receipt of [lint, oldLint]) {
  assert.equal(receipt.status, 'failed')
  assert.equal(receipt.exitCode, 1)
}
assert.equal(lint.source.headOid, candidate)
assert.equal(oldLint.source.headOid, base)
assert.deepEqual(lint.command, oldLint.command)
for (const [path, value] of Object.entries(lint.source.inputs))
  if (path !== 'app/scene-entities.ts') assert.equal(value, oldLint.source.inputs[path], path)
const diagnostics = receipt => receipt.stdout.trim().split('\n').map(line => line.replace(/:\d+:\d+(?=: (?:warning|error))/, ':<line>:<column>')).sort()
assert.equal(diagnostics(lint).length, 9)
assert.deepEqual(diagnostics(lint), diagnostics(oldLint))
console.log(JSON.stringify({ focusedCandidate: 'passed 8/8', actualUnmodifiedBase: 'failed: 7 passed, scaling failed at64 with2144 ID reads', pairedInputHashes: full.source.inputs, productionBaseUnchanged: true, damageAndBlastTailUnchanged: true, strictOxlintCandidate: 'failed', strictOxlintBase: 'failed', diagnosticMultiset: 'passed: nine exact inherited diagnostics; only numeric line/column prefixes normalized' }, null, 2))
